#!/usr/bin/env bash
# Compares the analog backend against the CPU backend:
#   - MUL_MAT level accuracy and speed  (test-analog-backend)
#   - the passes of the array model     (test-analog-kernels)
#   - model loading and throughput      (llama-analog-bench)
#   - perplexity                        (llama-perplexity)
#
# Nothing is downloaded: the models are generated by make-tiny-model.py and the corpus is taken
# from the repository itself.
#
# Usage:
#   benches/analog/compare.sh
#   GGML_ANALOG_BITS_W=2 benches/analog/compare.sh
#
# Environment:
#   BIN      build directory with the tools        (default: <repo>/build/bin)
#   WORK     working directory for models/results  (default: /tmp/llama-analog-bench)
#   THREADS  number of threads                     (default: nproc)
#   PROMPT   prompt size in tokens                 (default: 128)
#   GEN      generated tokens per run              (default: 16)
#   REPS     repetitions                           (default: 3)

set -euo pipefail

ROOT=$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)

BIN=${BIN:-$ROOT/build/bin}
WORK=${WORK:-/tmp/llama-analog-bench}
THREADS=${THREADS:-$(nproc)}
PROMPT=${PROMPT:-128}
GEN=${GEN:-16}
REPS=${REPS:-3}

MODEL=${MODEL:-$WORK/medium-q8_0.gguf}
CORPUS=${CORPUS:-$WORK/corpus.txt}

mkdir -p "$WORK"

for tool in llama-analog-bench llama-perplexity llama-cli test-analog-backend test-analog-kernels; do
    if [ ! -x "$BIN/$tool" ]; then
        echo "error: $BIN/$tool not found, build with -DGGML_ANALOG=ON first" >&2
        exit 1
    fi
done

if [ ! -f "$MODEL" ]; then
    echo "generating the test models .." >&2
    python3 "$ROOT/benches/analog/make-tiny-model.py" --out "$WORK/medium-f32.gguf" \
        --n-embd 256 --n-layer 4 --n-head 8 --n-ff 768 >&2
    "$BIN/llama-quantize" "$WORK/medium-f32.gguf" "$WORK/medium-q8_0.gguf" q8_0 "$THREADS" >&2
    "$BIN/llama-quantize" "$WORK/medium-f32.gguf" "$WORK/medium-q4_0.gguf" q4_0 "$THREADS" >&2
fi

if [ ! -f "$CORPUS" ]; then
    cat "$ROOT/README.md" "$ROOT/docs/build.md" "$ROOT/docs/development/HOWTO-add-model.md" \
        "$ROOT/ggml/include/ggml.h" > "$CORPUS"
fi

now_ms() { date +%s%N | cut -c1-13; }

# runs one backend configuration of llama-analog-bench and prints the table row plus the stats
bench() { # name, env..
    local name=$1; shift
    local out=$WORK/bench-$name
    local t0 t1

    t0=$(now_ms)
    env "$@" "$BIN/llama-analog-bench" -m "$MODEL" -p "$PROMPT" -n "$GEN" -r "$REPS" -t "$THREADS" -c 512 -q \
        > "$out.out" 2> "$out.err" || true
    t1=$(now_ms)

    # the first column is the backend of the run, replace it with the name of the configuration
    grep -E "^\| (cpu|analog)" "$out.out" | head -1 | \
        awk -F'|' -v n="$name" 'BEGIN{OFS="|"} {$2 = sprintf(" %-16s ", n); print}' || true

    local stats
    stats=$(grep "^analog: stats:" "$out.err" | sed 's/^analog: stats: //' || true)
    local dev
    dev=$(grep "^analog: modeled device:" "$out.out" | sed 's/^analog: modeled device: //' || true)

    if [ -n "$stats" ]; then
        echo
        echo "> array model: $stats"
    else
        echo
        echo "> wall time: $((t1 - t0)) ms"
    fi

    if [ -n "$dev" ]; then
        echo "> modeled device: $dev"
    fi

    echo
}

echo "# analog backend vs CPU backend"
echo
echo "| parameter | value |"
echo "| --- | --- |"
echo "| model | $(basename "$MODEL") ($(stat -c %s "$MODEL") bytes) |"
echo "| threads | $THREADS / $(nproc) |"
echo "| prompt / generation / repetitions | $PROMPT / $GEN / $REPS |"
echo "| array | cells ${GGML_ANALOG_BITS_W:-4} bit, DAC ${GGML_ANALOG_BITS_X:-8} bit, ADC ${GGML_ANALOG_BITS_ADC:-8} bit, tile ${GGML_ANALOG_TILE_COLS:-128} |"

echo
echo "## MUL_MAT, one operation at a time"
echo
"$BIN/test-analog-backend" 2>/dev/null | grep -vE "^$" || true

echo
echo "## Kernels and compute shaders of the passes"
echo
echo "The three passes of the array model (input DAC, programming, readout) exist as a scalar"
echo "reference, as parallel CPU kernels and as compute shaders, see docs/backend/ANALOG.md."
echo "Every path reproduces the reference bit for bit, which is what the kernel test checks"
echo "before it measures the speed."
echo
kernels_out=$("$BIN/test-analog-kernels" -r 5 2>/dev/null | grep -vE "^$" || true)
printf '%s\n' "$kernels_out"

if ! printf '%s\n' "$kernels_out" | grep -q "all kernel tests passed"; then
    echo "error: the kernels of the analog backend did not pass their tests" >&2
    exit 1
fi

echo
echo "The same passes dispatched to the mirror of the compute shaders have to reproduce the CPU"
echo "kernels on the whole model, not just on one operation:"
echo

if ! mirror_out=$("$BIN/test-analog-backend" -d shader 2>/dev/null) || \
   ! printf '%s\n' "$mirror_out" | grep -q "bit for bit against the CPU kernels"; then
    echo "error: the mirror of the compute shaders does not reproduce the CPU kernels" >&2
    exit 1
fi

printf '%s\n' "$mirror_out" | grep -E "^(the passes|main:)" || true

echo
echo "## Loading and throughput"
echo
echo "| configuration    |    load_ms | context_ms |  first_ms |     pp_ms |     tg_ms |"
echo "| ---------------- | ---------: | ---------: | --------: | --------: | --------: |"

bench "cpu"          GGML_ANALOG_ENABLE=0
bench "analog-ideal" GGML_ANALOG_ENABLE=1 GGML_ANALOG_IDEAL=1
bench "analog"       GGML_ANALOG_ENABLE=1
bench "analog-1thread" GGML_ANALOG_ENABLE=1 GGML_ANALOG_N_THREADS=1
bench "analog-shader"  GGML_ANALOG_ENABLE=1 GGML_ANALOG_DISPATCH=shader
bench "analog-vulkan"  GGML_ANALOG_ENABLE=1 GGML_ANALOG_DISPATCH=vulkan
bench "analog-2bit"  GGML_ANALOG_ENABLE=1 GGML_ANALOG_BITS_W=2 GGML_ANALOG_BITS_ADC=6

echo
echo "## Perplexity (8 chunks of the repo documentation)"
echo
echo "| backend        |       PPL | time [s] |"
echo "| -------------- | --------: | -------: |"

ppl() { # name, env..
    local name=$1; shift
    local log=$WORK/perplexity-$name.log
    local val=""
    local t0 t1

    # a second attempt in case the machine was busy and the run was cut short
    for _ in 1 2; do
        t0=$(now_ms)
        env "$@" "$BIN/llama-perplexity" -m "$MODEL" -f "$CORPUS" -c 512 -b 512 --chunks 8 -t "$THREADS" \
            > "$log" 2>&1 || true
        t1=$(now_ms)

        val=$(grep -oE "Final estimate: PPL = [0-9.]+" "$log" | tail -1 | grep -oE "[0-9.]+$" || true)

        if [ -n "$val" ]; then
            break
        fi

        echo "warning: the $name perplexity run did not finish, retrying" >&2
    done

    local secs
    secs=$(awk "BEGIN{printf \"%.2f\", ($t1 - $t0)/1000}")

    printf "| %-14s | %9s | %8s |\n" "$name" "${val:--}" "$secs"
}

ppl "cpu"          GGML_ANALOG_ENABLE=0
ppl "analog-ideal" GGML_ANALOG_ENABLE=1 GGML_ANALOG_IDEAL=1
ppl "analog"       GGML_ANALOG_ENABLE=1
ppl "analog-2bit"  GGML_ANALOG_ENABLE=1 GGML_ANALOG_BITS_W=2 GGML_ANALOG_BITS_ADC=6

echo
echo "## Logits of the same prompts"
echo
echo "The reference logits are measured with the CPU backend alone, the analog backend is then"
echo "matched against them. The prompts are fixed, so both runs see exactly the same input."
echo

logits() { # name, env..
    local name=$1; shift

    env "$@" "$BIN/llama-analog-bench" -m "$MODEL" -p "$PROMPT" -n "$GEN" -r "$REPS" -t "$THREADS" -c 512 \
        -q --logits "$WORK/logits-$name.bin" > /dev/null 2>&1 || true
}

logits "cpu"          GGML_ANALOG_ENABLE=0
logits "analog-ideal" GGML_ANALOG_ENABLE=1 GGML_ANALOG_IDEAL=1
logits "analog"       GGML_ANALOG_ENABLE=1

for name in analog-ideal analog; do
    echo
    echo "analog ($name) against the CPU backend:"
    echo
    "$BIN/llama-analog-bench" --compare "$WORK/logits-cpu.bin" "$WORK/logits-$name.bin" 2>/dev/null | grep -v "logits:" || true
done

echo
echo "Raw logs: $WORK"
